#!/usr/bin/env python3
"""A standalone corrective shell highlighter and quoting rewriter."""
import os
import re
import sys

# Each output fragment carries a foreground class or an edit class.  Rendering
# the same stream in different ways implements the diff and plain-text modes.
STYLES = {
    '': '', 'key': '0;1', 'cmd': '0;38;2;192;0;128',
    'lhs': '0;38;2;0;127;255', 'var': '0;38;2;63;127;207',
    'dq': '0;38;2;255;0;0', 'sq': '0;38;2;255;204;85',
    'ansi': '0;38;2;255;128;0', 'esc': '0;1;38;2;255;0;128',
    'comment': '0;1;3;38;2;120;144;96', 'expr': '0;38;2;192;0;192',
    'here': '0;38;2;128;32;0', 'add': '0;42', 'del': '0;41',
}
IDENT = re.compile(r'[a-zA-Z_][a-zA-Z_0-9]*')
DIGITS = re.compile(r'[0-9]+')
KEYWORDS = set('if then else elif fi do done while until function local declare export readonly ! { }'.split())
SPACE = ' \t\r\n'
TAIL = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789')
BRIDGE = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789+,-./:=@[]^{}~')
EOF_MESSAGE = ("Unexpected end of file\n"
               "The file's end was reached without closing all sytactic scopes.\n"
               "Either, the parser got lost, or the file is truncated or malformed.\n")
PITFALL_MESSAGE = ("This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\n"
    'Try this and be shocked: f() { echo "$9" "$10"; }; f a b c d e f g h i j\n\n'
    'Here is where braces should be used to disambiguate, e.g. "${10}" vs "${1}0".\n\n'
    'Syntactic pitfalls are deemed too dangerous to fix automatically\n'
    '(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n'
    '* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n'
    '* Fixing its look would make a likely bug look intentional.\n')

HELP = '''Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md

'''

class ParseFailure(Exception):
    def __init__(self, kind='eof', start=0, end=0):
        self.kind, self.start, self.end = kind, start, end

class Parser:
    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.p = 0
        self.events = []
        self.changed = False
        self.error = None

    def emit(self, text, color='', edit=''):
        if not text:
            return
        self.events.append((text, color, edit))
        if edit:
            self.changed = True

    def take(self, end, color='', edit=''):
        self.emit(self.s[self.p:end], color, edit)
        self.p = end

    def add(self, text):
        self.emit(text, '', 'add')

    def delete(self, end, color=''):
        self.take(end, color, 'del')

    def at(self, text):
        return self.s.startswith(text, self.p)

    def char(self, pos=None):
        if pos is None:
            pos = self.p
        return self.s[pos] if pos < self.n else ''

    def run(self):
        try:
            self.code()
        except ParseFailure as err:
            self.error = err
        except RecursionError:
            self.error = ParseFailure()
        return self

    def diagnostic(self):
        if self.error.kind == 'eof':
            return EOF_MESSAGE.encode()
        a, b = self.error.start, self.error.end
        line_a = self.s.rfind('\n', 0, a) + 1
        line_b = self.s.find('\n', b)
        if line_b < 0:
            line_b = self.n
        return (b'Unsupported syntax: Syntactic pitfall\n' +
                self.s[line_a:line_b].encode('latin1') + b'\n' +
                b' ' * (a-line_a) + b'^' * (b-a) + b'\n' + PITFALL_MESSAGE.encode())

    def render(self, mode):
        out = []
        old = ''
        for text, color, edit in self.events:
            if mode in ('transform', 'replace'):
                if edit != 'del':
                    out.append(text)
                continue
            if mode == 'syntax':
                if edit == 'add':
                    continue
                cls = color
            else:
                cls = edit if edit else (color if mode == 'syntax-suggest' else '')
            if cls != old:
                out.append('\x1b[' + STYLES[cls] + 'm')
                old = cls
            out.append(text)
        if old:
            out.append('\x1b[m')
        if self.error:
            out.append('\n')
        return ''.join(out).encode('latin1')

    def escape(self):
        end = min(self.n, self.p + 2)
        missing = end < self.p + 2
        self.take(end, 'esc')
        if missing:
            raise ParseFailure()

    def single(self, ansi=False):
        color = 'ansi' if ansi else 'sq'
        self.take(self.p + (2 if ansi else 1), color)
        while self.p < self.n:
            if self.char() == "'":
                self.take(self.p + 1, color)
                return
            if ansi and self.char() == '\\':
                self.escape()
            else:
                start = self.p
                while self.p < self.n and self.char() != "'" and not (ansi and self.char() == '\\'):
                    self.p += 1
                self.emit(self.s[start:self.p], color)
        raise ParseFailure()

    def brace_end(self, p):
        # Parameter expansions nest only on another dollar-brace expansion.
        depth = 1
        j = p + 2
        while j < self.n:
            if self.s[j] == '\\':
                j += 2
            elif self.s.startswith('${', j):
                depth += 1
                j += 2
            elif self.s[j] == '}':
                depth -= 1
                j += 1
                if not depth:
                    return j, True
            else:
                j += 1
        return self.n, False

    def expansion(self, p=None):
        if p is None:
            p = self.p
        if p >= self.n or self.s[p] != '$' or p+1 >= self.n:
            return None
        c = self.s[p+1]
        if c == '{':
            end, closed = self.brace_end(p)
            safe = p+2 < self.n and self.s[p+2] in '#!?$'
            return ('brace', end, safe, closed)
        if c == '(':
            return ('arith' if self.s.startswith('$((',p) else 'sub', p+2, self.s.startswith('$((',p), True)
        if c in '@*?!#$-':
            return ('special', p+2, c in '?!#$', True)
        m = IDENT.match(self.s, p+1)
        if m:
            return ('name', m.end(), False, True)
        m = DIGITS.match(self.s, p+1)
        if m:
            return ('number', m.end(), False, True)
        return None

    def brace_needed(self, end):
        while end < self.n and self.s[end] == '"':
            end += 1
        return end == self.n or self.s[end] in TAIL

    def variable(self, modify=False, array=False):
        info = self.expansion()
        kind, end, safe, closed = info
        start = self.p
        if kind == 'number' and end - start > 2:
            raise ParseFailure('pitfall', start, end)
        if kind == 'name' and modify and (array or self.brace_needed(end)):
            self.take(start+1, 'var')
            self.add('{')
            self.take(end, 'var')
            self.add('[@]}' if array else '}')
        elif kind == 'brace':
            body = self.s[start+2:end-1] if closed else ''
            plain = IDENT.fullmatch(body)
            if modify and plain and not self.brace_needed(end):
                self.take(start+1, 'var')
                self.delete(start+2, 'var')
                self.take(end-1, 'var')
                self.delete(end, 'var')
            elif modify:
                m = re.match(r'\$\{[a-zA-Z_][a-zA-Z_0-9]*\[\*\]', self.s[start:end])
                if m:
                    star = start + m.end() - 2
                    self.take(star, 'var')
                    self.delete(star+1, 'var')
                    self.add('@')
                    self.take(end, 'var')
                else:
                    self.take(end, 'var')
            else:
                self.take(end, 'var')
        else:
            self.take(end, 'var')
        if not closed:
            raise ParseFailure()

    def double(self, merge=False):
        # Standalone braced variables may be simplified, while interpolated
        # strings retain their author's brace style.
        start = self.p
        if merge:
            self.delete(start+1, 'dq')
        else:
            self.take(start+1, 'dq')
        simple = False
        if self.at('${'):
            end, closed = self.brace_end(self.p)
            simple = closed and end < self.n and self.s[end] == '"'
        first = True
        while self.p < self.n:
            c = self.char()
            if c == '"':
                self.take(self.p+1, 'dq')
                return
            if c == '\\':
                self.escape()
            elif c == '`':
                self.backtick(True)
            elif c == '$' and self.expansion():
                info = self.expansion()
                if info[0] == 'sub':
                    self.substitution()
                elif info[0] == 'arith':
                    self.expression('$((', '))')
                else:
                    # Only names in braces are simplified in an existing DQ.
                    mod = first and simple and info[0] == 'brace'
                    self.variable(modify=mod)
            else:
                self.take(self.p+1, 'dq')
            first = False
        raise ParseFailure()

    def substitution(self):
        self.take(self.p+2)
        self.code(stop=')')
        if self.p == self.n:
            raise ParseFailure()
        self.take(self.p+1)

    def backtick(self, rewrite=False):
        if rewrite:
            self.delete(self.p+1)
            self.add('$(')
        else:
            self.take(self.p+1)
        self.code(stop='`')
        if self.p == self.n:
            raise ParseFailure()
        if rewrite:
            self.delete(self.p+1)
            self.add(')')
        else:
            self.take(self.p+1)

    def expression(self, opening, closing):
        self.take(self.p+len(opening), 'expr')
        depth = 0
        while self.p < self.n:
            if depth == 0 and self.at(closing):
                self.take(self.p+len(closing), 'expr')
                return
            c = self.char()
            if c == '"':
                self.double()
            elif c == "'":
                self.single()
            elif c == '\\':
                self.escape()
            elif c == '`':
                self.backtick(False)
            elif self.at("$'"):
                self.single(True)
            elif c == '$' and self.expansion():
                info = self.expansion()
                if info[0] == 'sub':
                    self.substitution()
                elif info[0] == 'arith':
                    self.expression('$((', '))')
                else:
                    self.variable()
            else:
                if closing == '))':
                    if c == '(':
                        depth += 1
                    elif c == ')' and depth:
                        depth -= 1
                self.take(self.p+1, 'expr')
        raise ParseFailure()

    def quote_run(self, array=False):
        # A dollar-star that initiates a quote is a special, isolated rewrite.
        info = self.expansion()
        if info and info[0] == 'number' and info[1] - self.p > 2:
            raise ParseFailure('pitfall', self.p, info[1])
        self.add('"')
        if self.at('$*'):
            self.take(self.p+1, 'var')
            self.delete(self.p+1, 'var')
            self.add('@"')
            return
        while True:
            if self.char() == '`':
                self.backtick(True)
            else:
                info = self.expansion()
                if info[0] == 'sub':
                    self.substitution()
                elif info[0] == 'arith':
                    self.expression('$((', '))')
                else:
                    self.variable(modify=info[0] in ('brace','name'), array=array)
            array = False
            j = self.p
            while j < self.n and self.s[j] in BRIDGE:
                j += 1
            if j < self.n and self.s[j] == '"':
                self.take(j, 'dq')
                self.double(merge=True)
                return
            if j < self.n and (self.s[j] == '`' or self.expansion(j)):
                self.take(j, 'dq')
                continue
            self.add('"')
            return

    def component(self, color='', safe=False, array=False):
        c = self.char()
        if c == '\\':
            self.escape()
            return True
        if c == "'":
            self.single()
            return True
        if c == '"':
            self.double()
            return True
        if self.at("$'"):
            self.single(True)
            return True
        if c == '`':
            if safe:
                self.backtick(False)
            else:
                self.quote_run()
            return True
        if c == '$':
            info = self.expansion()
            if info:
                if not safe and not info[2]:
                    self.quote_run(array)
                elif info[0] == 'sub':
                    self.substitution()
                elif info[0] == 'arith':
                    self.expression('$((', '))')
                else:
                    self.variable()
                return True
        return False

    def comment(self):
        end = self.s.find('\n', self.p)
        if end < 0:
            end = self.n
        self.take(end, 'comment')

    def heredoc(self):
        begin = self.p
        j = self.p+2
        if j < self.n and self.s[j] == '-':
            j += 1
        while j < self.n and self.s[j] in ' \t':
            j += 1
        delim = []
        quote = ''
        while j < self.n:
            c = self.s[j]
            if not quote and c in SPACE:
                break
            if c in "\"'":
                if quote == c:
                    quote = ''
                elif not quote:
                    quote = c
                else:
                    delim.append(c)
            elif c == '\\' and j+1 < self.n:
                j += 1
                delim.append(self.s[j])
            else:
                delim.append(c)
            j += 1
        delimiter = ''.join(delim)
        line_end = self.s.find('\n', j)
        found = self.s.find(delimiter, line_end+1) if line_end >= 0 and delimiter else -1
        if found < 0:
            self.take(self.n, 'here')
            raise ParseFailure()
        self.take(found+len(delimiter), 'here')

    def assignment_end(self):
        m = IDENT.match(self.s, self.p)
        if not m:
            return None
        j = m.end()
        if j < self.n and self.s[j] == '[':
            k = self.s.find(']', j+1)
            if k < 0:
                return None
            j = k+1
        lhs = j
        if j < self.n and self.s[j] == '+':
            j += 1
        if j < self.n and self.s[j] == '=':
            return lhs, j+1
        return None

    def word(self, color='', safe=False, stop=''):
        while self.p < self.n:
            c = self.char()
            if c in SPACE+';&|' or (stop and self.at(stop)):
                return
            if c == '#' and color != 'cmd':
                self.comment()
                return
            if c == '(' and color == 'cmd':
                return
            if not safe and c in '<>' and color == 'cmd':
                return
            if self.at('<<') and not self.at('<<<'):
                self.heredoc()
            elif self.component(color, safe):
                pass
            else:
                self.take(self.p+1, color)

    def assignment(self, stop=''):
        lhs, end = self.assignment_end()
        self.take(lhs, 'lhs')
        self.take(end)
        if self.char() == '(':
            self.take(self.p+1)
            self.arguments_until(')')
            if self.p == self.n:
                raise ParseFailure()
            self.take(self.p+1)
        else:
            self.word(safe=True, stop=stop)

    def arguments_until(self, end):
        while self.p < self.n and not self.at(end):
            if self.char() == '#':
                self.comment()
            elif self.at('<<') and not self.at('<<<'):
                self.heredoc()
            elif self.component():
                pass
            else:
                self.take(self.p+1)

    def for_header(self, name):
        self.take(self.p+len(name), 'key')
        j = self.p
        while j < self.n and self.s[j] in ' \t\r':
            j += 1
        self.take(j, 'key')
        if self.at('(('):
            self.expression('((', '))')
            return
        m = IDENT.match(self.s, self.p)
        if m:
            self.take(m.end(), 'lhs')
            j = self.p
            while j < self.n and self.s[j] in ' \t\r':
                j += 1
            self.take(j, 'key')
        start = self.p
        arr_match = re.match(r'in +\$([a-zA-Z_][a-zA-Z_0-9]*)( *)(?=[;\n])', self.s[start:])
        if arr_match:
            var_start = start + self.s[start:start+arr_match.end()].find('$')
            self.take(var_start)
            self.quote_run(array=True)
            self.take(start+arr_match.end(), 'key')
        while self.p < self.n and self.char() not in ';\n':
            if self.char() == '#':
                self.comment()
            elif self.component():
                pass
            else:
                self.take(self.p+1)
        if self.p == self.n:
            raise ParseFailure()

    def case_statement(self):
        self.take(self.p+4, 'key')
        # The word selector and the 'in' marker share a safe keyword scope.
        while self.p < self.n:
            if self.s.startswith('in',self.p) and (self.p==0 or self.s[self.p-1] in SPACE) and (self.p+2==self.n or self.s[self.p+2] in SPACE+';'):
                self.take(self.p+2, 'key')
                break
            if self.component('key', True):
                continue
            self.take(self.p+1, 'key')
        else:
            raise ParseFailure()
        while self.p < self.n:
            while self.p < self.n:
                if self.at('esac') and (self.p+4==self.n or self.s[self.p+4] in SPACE+';)&|'):
                    self.take(self.p+4, 'key')
                    return
                if self.char() == ')':
                    self.take(self.p+1)
                    break
                if self.char() == '#':
                    self.comment()
                elif self.component('',True):
                    pass
                else:
                    self.take(self.p+1)
            else:
                raise ParseFailure()
            self.code(stop=';;')
            if self.at(';;'):
                self.take(self.p+2)
            else:
                raise ParseFailure()
        raise ParseFailure()

    def test_command(self, name):
        # Recognition here is deliberately literal: the idiom includes exactly
        # one ASCII space, not arbitrary shell whitespace.
        self.take(self.p+len(name)+1, 'cmd')
        if (self.at('-n ') or self.at('-z ')) and self.p+3 < self.n:
            scope = self.p+3
            if self.s[scope] in '\\\'"`' or self.expansion(scope) or self.s.startswith("$'",scope):
                op = ' != ""' if self.char(self.p+1) == 'n' else ' = ""'
                self.delete(self.p+3)
                self.component()
                self.add(op)
                return
        if self.char() == 'x':
            # Check the whole first scope before modifying either x prefix.
            end = self.scope_end(self.p+1)
            if end is not None:
                m = re.match(r' (==|!=|=) x', self.s[end:])
                if m:
                    self.delete(self.p+1)
                    self.component()
                    self.take(end + m.end()-1)
                    self.delete(self.p+1)
                    if self.p == self.n or self.char() in SPACE+';&|':
                        self.add('""')
                    return

    def scope_end(self, p):
        if p >= self.n:
            return None
        c = self.s[p]
        if c == '\\':
            return min(p+2,self.n)
        if c == "'":
            end = self.s.find("'",p+1)
            return end+1 if end>=0 else None
        # Use an isolated scanner to measure one rendered scope.  This also
        # respects concatenated expansions covered by an inserted quote.
        if c in '$"`':
            probe = Parser(self.s)
            probe.p = p
            try:
                if probe.component():
                    return probe.p
            except (ParseFailure, RecursionError):
                pass
        return None

    def code(self, stop=''):
        command = True
        while self.p < self.n:
            if stop and self.at(stop):
                return
            c = self.char()
            if c in SPACE:
                self.take(self.p+1)
                if c == '\n':
                    command = True
                continue
            if c == '#':
                self.comment()
                continue
            if c in ';&|':
                self.take(self.p+1)
                command = True
                continue
            if command:
                if self.at('(('):
                    self.expression('((', '))')
                    command = False
                    continue
                if self.at('[['):
                    self.expression('[[', ']]')
                    command = False
                    continue
                if c == '(':
                    self.take(self.p+1)
                    self.code(stop=')')
                    if self.p == self.n:
                        raise ParseFailure()
                    self.take(self.p+1)
                    command = False
                    continue
                if self.at('<<') and not self.at('<<<'):
                    self.heredoc()
                    command = False
                    continue
                if c in '<>':
                    self.take(self.p+1)
                    continue
                if self.assignment_end():
                    self.assignment(stop)
                    continue
                m = re.match(r'[^\s;&|(< >$\'"`\\]+', self.s[self.p:])
                name = m[0] if m else ''
                if name in KEYWORDS:
                    self.take(self.p+len(name), 'key')
                    continue
                if name in ('for','select'):
                    self.for_header(name)
                    command = False
                    continue
                if name == 'case':
                    self.case_statement()
                    command = False
                    continue
                if name in ('[','test') and self.p+len(name)<self.n and self.s[self.p+len(name)] == ' ' and (self.p+len(name)+1==self.n or self.s[self.p+len(name)+1] not in ' \t\r\n'):
                    self.test_command(name)
                    command = False
                    continue
                old = self.p
                self.word('cmd',stop=stop)
                command = False
                if self.p == old:
                    self.take(self.p+1)
                if self.at('()'):
                    self.take(self.p+2)
                    command = True
                continue
            if self.at('<<') and not self.at('<<<'):
                self.heredoc()
            elif self.component():
                pass
            else:
                self.take(self.p+1)


def error_bytes(name, err):
    return os.fsencode(name) + b': ' + os.strerror(err.errno).encode() + (' (os error %d)\n' % err.errno).encode()


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    mode = 'syntax-suggest'
    options = True
    status = 0
    stdout, stderr = sys.stdout.buffer, sys.stderr.buffer
    for arg in argv:
        if options and arg.startswith('-'):
            if arg == '--':
                options = False
            elif arg in ('-h','--help'):
                stdout.write(HELP.encode())
            elif arg == '--version':
                stdout.write(b'4.3.1\n')
            elif arg in ('--suggest','--syntax','--syntax-suggest','--transform','--check','--replace'):
                mode = arg[2:]
            else:
                stderr.write(os.fsencode(arg)+b': No such option.\n')
                return 3
            continue
        read_failure = None
        if arg:
            try:
                fd = os.open(arg, os.O_RDONLY)
            except OSError as err:
                stderr.write(error_bytes(arg,err))
                status = 1
                continue
            try:
                with os.fdopen(fd,'rb') as f:
                    data = f.read()
            except OSError as err:
                read_failure = err
                data = b''
        else:
            try:
                data = sys.stdin.buffer.read()
            except OSError as err:
                read_failure = err
                data = b''
        if read_failure:
            if mode == 'check':
                return 2
            if mode != 'replace' or not arg:
                stdout.write(b'\n')
            stderr.write(error_bytes(arg, read_failure))
            status = 1
            continue
        parser = Parser(data.decode('latin1')).run()
        if mode == 'check':
            if parser.changed or parser.error:
                return 2
            continue
        if parser.error:
            status = 1
            stderr.write(os.fsencode(arg)+b': '+parser.diagnostic())
        if mode == 'replace' and arg:
            if not parser.error and parser.changed:
                try:
                    with open(arg,'wb') as f:
                        f.write(parser.render('transform'))
                except OSError as err:
                    stderr.write(error_bytes(arg,err))
                    status = 1
        else:
            stdout.write(parser.render(mode))
    return status

if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except BrokenPipeError:
            pass
        sys.exit(1)
