            if self.component('key', True):
                continue
            self.take(self.p+1, 'key')
        else:
            raise ParseFailure()
        while self.p < self.n:
            while self.p < self.n:
                if self.at('esac') and (self.p+4==self.n or self.s[self.p+4] in SPACE+';)&|'):
                    self.take(self.p+4, 'key')
                    return
                if self.char() == ')':
                    self.take(self.p+1)
                    break
                if self.char() == '#':
                    self.comment()
                elif self.component('',True):
                    pass
                else:
                    self.take(self.p+1)
            else:
                raise ParseFailure()
            self.code(stop=';;')
            if self.at(';;'):
                self.take(self.p+2)
            else:
                raise ParseFailure()
