            probe.p = p
            try:
                if probe.component():
                    return probe.p
            except (ParseFailure, RecursionError):
                pass
        return None

    def code(self, stop=''):
        command = True
        while self.p < self.n:
            if stop and self.at(stop):
                return
            c = self.char()
            if c in SPACE:
                self.take(self.p+1)
                if c == '\n':
                    command = True
                continue
            if c == '#':
                self.comment()
                continue
            if c in ';&|':
                self.take(self.p+1)
                command = True
                continue
            if command:
                if self.at('(('):
                    self.expression('((', '))')
                    command = False
                    continue
                if self.at('[['):
                    self.expression('[[', ']]')
